components.css:
.ds-btn-primary { display:inline-flex; align-items:center; justify-content:center; gap:8px; line-height:1; min-height:38px; padding:0 14px; border:1px solid transparent; border-radius:var(--radius-md); background:var(--accent-solid); color:var(--accent-fg); font-family:var(--font-sans); font-weight:500; font-size:var(--text-small); letter-spacing:-0.005em; cursor:pointer; white-space:nowrap; transition:background var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out), transform var(--dur-press) var(--ease-out); }
.ds-btn-primary .ds-ico { width:1em; height:1em; }
.ds-btn-primary:hover { background:var(--accent-hover); }
.ds-btn-primary:active { transform:translateY(1px); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: 0 0 0 3px var(--accent-soft); }

.ds-btn-ghost { display:inline-flex; align-items:center; justify-content:center; gap:8px; line-height:1; min-height:38px; padding:0 14px; border:1px solid var(--border-strong); border-radius:var(--radius-md); background:transparent; color:var(--text); font-family:var(--font-sans); font-weight:500; font-size:var(--text-small); cursor:pointer; transition:background var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out); }
.ds-btn-ghost:hover { background:var(--surface-2); }
.ds-btn-ghost:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: 0 0 0 3px var(--accent-soft); }

.ds-rating { position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:4px; min-height:56px; padding:14px 8px; border:1px solid var(--border-strong); border-radius:var(--radius-md); background:var(--surface); font-family:var(--font-sans); cursor:pointer; transition:background var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out); }
.ds-rating-good { border-color:var(--good-text); color:var(--good-text); }
.ds-rating-label { font-size:var(--text-body); font-weight:600; letter-spacing:-0.005em; }
.ds-rating-key { position:absolute; top:6px; left:8px; padding:1px 5px; border:1px solid currentColor; border-radius:4px; background:transparent; font-size:var(--text-micro); font-weight:500; opacity:.75; }
.ds-rating:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: 0 0 0 3px var(--accent-soft); }

.ds-rating.is-pressed { background:var(--good-fill); border-color:var(--good-fill); color:var(--good-ink); }
.ds-rating.is-pressed .ds-rating-key { opacity:.95; }
.ds-rating.is-pressed:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: 0 0 0 3px var(--accent-soft); }

.ds-chip { display:inline-flex; align-items:center; min-height:32px; padding:4px 12px; border:1px solid var(--border); border-radius:var(--radius-pill); background:var(--surface-2); color:var(--text-muted); font-family:var(--font-sans); font-size:var(--text-small); font-weight:500; cursor:pointer; transition:background var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out); }
.ds-chip:hover { background:var(--surface-3); color:var(--text); }
.ds-chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: 0 0 0 3px var(--accent-soft); }

.ds-card { position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:6px; max-width:640px; min-height:320px; padding:36px 40px; border:1px solid var(--border-strong); border-radius:var(--radius-xl); background:var(--surface); box-shadow:var(--shadow-md); text-align:center; font-family:var(--font-sans); }
.ds-card-meta { position:absolute; top:18px; left:22px; right:22px; display:flex; align-items:center; justify-content:space-between; }
.ds-card-level { font-size:var(--text-micro); font-weight:500; color:var(--text-muted); letter-spacing:0.02em; }
.ds-card-audio { display:inline-flex; align-items:center; justify-content:center; width:36px; height:36px; border:1px solid var(--border); border-radius:var(--radius-md); background:var(--surface-2); color:var(--text-muted); cursor:pointer; transition:color var(--dur-fast) var(--ease-out), background var(--dur-fast) var(--ease-out); }
.ds-card-audio .ds-ico { width:18px; height:18px; }
.ds-card-audio:hover { color:var(--accent); }
.ds-card-audio:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: 0 0 0 3px var(--accent-soft); }
.ds-card-word { font-family:var(--font-display); font-size:var(--text-lead); font-weight:400; color:var(--text-strong); }
.ds-card-sub { font-size:var(--text-meta); color:var(--text-muted); }

.ds-input { width:100%; padding:10px 14px; border:1px solid var(--border-strong); border-radius:var(--radius-md); background:var(--surface); color:var(--text); font-family:var(--font-sans); font-size:var(--text-body); transition:border-color var(--dur-fast) var(--ease-out), box-shadow var(--dur-fast) var(--ease-out); }
.ds-input:focus { outline:none; border-color:var(--accent); box-shadow:0 0 0 3px var(--accent-soft); }
.ds-input:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: 0 0 0 3px var(--accent-soft); }

.ds-nav { display:inline-flex; align-items:center; gap:6px; padding:7px 12px; border-radius:var(--radius-md); color:var(--text-muted); font-family:var(--font-sans); font-size:var(--text-small); font-weight:500; text-decoration:none; transition:background var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out); }
.ds-nav .ds-ico { width:16px; height:16px; }
.ds-nav:hover { background:var(--surface-2); color:var(--text); }
.ds-nav-active { background:var(--surface-2); color:var(--text-strong); }
.ds-nav:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: 0 0 0 3px var(--accent-soft); }

.ds-filter { display:flex; align-items:center; gap:8px; width:100%; min-height:var(--tap-min); padding:0 12px; background:var(--surface); border:1px solid var(--border-strong); border-radius:var(--radius-md); color:var(--text); font-family:var(--font-sans); font-size:var(--text-body); text-align:left; cursor:pointer; transition:background var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out); }
.ds-filter:hover { background:var(--surface-2); }
.ds-filter-label { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-weight:500; }
.ds-filter[aria-expanded="true"] { border-color:var(--accent); }
.ds-filter[aria-expanded="true"] .ds-ico:last-child { transform:rotate(180deg); }
